import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'
import posthog from 'posthog-js'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { teamLogic } from 'scenes/teamLogic'

import { calendarSyncSyncNowCreate } from 'products/customer_analytics/frontend/generated/api'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface calendarSyncLogicValues {
    currentTeamId: number | null // teamLogic
    syncingIntegrationIds: number[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface calendarSyncLogicActions {
    syncFinished: (integrationId: number) => {
        integrationId: number
    }
    syncNow: (integrationId: number) => {
        integrationId: number
    }
}

export type calendarSyncLogicType = MakeLogicType<calendarSyncLogicValues, calendarSyncLogicActions>

export const calendarSyncLogic = kea<calendarSyncLogicType>([
    path(['scenes', 'customerAnalytics', 'configuration', 'calendarSyncLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    actions({
        syncNow: (integrationId: number) => ({ integrationId }),
        syncFinished: (integrationId: number) => ({ integrationId }),
    }),
    reducers({
        syncingIntegrationIds: [
            [] as number[],
            {
                syncNow: (state, { integrationId }) =>
                    state.includes(integrationId) ? state : [...state, integrationId],
                syncFinished: (state, { integrationId }) => state.filter((id) => id !== integrationId),
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        syncNow: async ({ integrationId }) => {
            try {
                const result = await calendarSyncSyncNowCreate(String(values.currentTeamId), {
                    integration_id: integrationId,
                })
                if (result.status === 'already_running') {
                    lemonToast.info('A sync for this calendar is already running')
                } else {
                    lemonToast.success('Calendar sync started. New meetings appear in a few minutes.')
                }
            } catch (error) {
                posthog.captureException(error as Error, { scope: 'calendarSyncLogic.syncNow' })
                lemonToast.error('Failed to start the calendar sync')
            } finally {
                actions.syncFinished(integrationId)
            }
        },
    })),
])
